let vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vUV;

	void main() {
		vUV = aTexCoord;

		vec4 position = vec4(aPosition, 1.0);
		position.xy = position.xy * 2.0 - 1.0;
		gl_Position = position;
	}
`;

let frag = `
	precision mediump float;
	#define PI 3.14159265359
	#define TAU 6.28318530718

	// dist from rotating spot point center, radius, angle
	float distCircRad( in vec2 uv, in vec2 c, in float r, in float a) {
		vec2 p = c + vec2(cos(a), sin(a)) * r;
		return length(uv - p);
	}

	// dist from segment point a, point b
	float distSegment( in vec2 p, in vec2 a, in vec2 b ) {
		vec2 pa = p-a, ba = b-a;
		float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
		return max(0., length( pa - ba*h ));
	}

	// dclr for NeonBar
	vec3 clrNeonBar( in vec2 p, in vec4 _bar, in vec4 _bcol ) {
		float angle = _bar.w;
		float bpos_z = 0.05;
		// bar.cag = bar.ang + bar.dag * time;
		vec2 w = vec2(cos(angle),sin(angle)) * bpos_z * 0.5;
		vec2  a = vec2(_bar.x, _bar.y) + w;
		vec2  b = vec2(_bar.x, _bar.y) - w;
		float d = distSegment(p, a, b);
		float br =  0.0025 / d; // bar.z / d;
		br = min(1.86, br); // reduce overglue
		// br = smoothstep(.00012, 0.91, br);
		return vec3(br) * vec3(_bcol.r, _bcol.g, _bcol.b) * _bcol.a; 
	}

    /**
     * Rand & Noise
     */

    float random ( in vec2 st ) {
        return fract(sin(dot(st.xy, vec2(12.9898,78.233)))*43758.5453123);
    }

    // 2D Noise based on Morgan McGuire @morgan3d // https://www.shadertoy.com/view/4dS3Wd
    float noise ( in vec2 st ) {
        vec2 i = floor(st);
        vec2 f = fract(st);

        // Four corners in 2D of a tile
        float a = random(i);
        float b = random(i + vec2(1.0, 0.0));
        float c = random(i + vec2(0.0, 1.0));
        float d = random(i + vec2(1.0, 1.0));

        // Smooth Interpolation

        // Cubic Hermine Curve.  Same as SmoothStep()
        vec2 u = f*f*(3.0-2.0*f);
        // u = smoothstep(0.,1.,f);

        // Mix 4 coorners percentages
        return mix(a, b, u.x) +
                (c - a)* u.y * (1.0 - u.x) +
                (d - b) * u.x * u.y;
    }

	varying vec2 vUV;

	// note that the type of this uniform is vec2
	uniform vec2 u_res;
	uniform vec2 u_mouse;
	uniform float u_time;

  // x, y, l, angle, r, g, b, intense
  uniform int u_bnum; // bars length
	uniform vec4 u_bars[200]; // vec4(x, y, intense, angle), max p5array length = 4 * 200 = 800

	void main() {
		vec2 uv = (vUV - 0.5) * 2.; //  
		uv *= u_res.x / u_res.y;
    // uv = vUV; // 0..1

    float d = distance(u_mouse, uv);
		vec3 clr = vec3(uv.x, uv.y, 0.0) * 0.3;
    clr = vec3(.0, .0, .04);

		// clr = vec3(noise(u_bars[0].xy*u_time), noise(u_bars[0].xy*u_time*3.14), noise(u_bars[0].xy*u_time*31.4)) * u_bars[0].z;
		// clr = vec3(u_mouse.x * u_time, u_mouse.y, u_mouse.x*u_mouse.y);
		for (int i = 0; i < 200; i++) {
			if (i >= u_bnum) break;
			vec4 bcol = vec4(noise(u_bars[i].xy*u_time), noise(u_bars[i].xy*u_time*3.14), noise(u_bars[i].xy*u_time*31.4), u_bars[i].z);
			clr += clrNeonBar(uv, u_bars[i], bcol);
		}


		// reduce color/intensity spectrum 1..256
		/*
		float f = 16.;
		clr.r = floor(clr.r*f)/f;
		clr.g = floor(clr.g*f)/f;
		clr.b = floor(clr.b*f)/f;
		*/

		gl_FragColor = vec4(clr, 1.0);
	}
`;


