/*
	NEON BAR Class
*/
class Bar {
  constructor(cx, cy, w, h, col, angle = 0) {
    this.cx = cx;
    this.cy = cy;
    this.w = w;
    this.h = h;
    this.a = angle;
    this.col = col;
    this.act = true;
  }

  draw(txt) {
    if (!this.act) return;

    push();
    blendMode(ADD); // combine colors

    rectMode(CENTER);
    translate(this.cx * width / 2, this.cy * height / 2);
    rotate(this.a);
    noStroke();
    drawingContext.shadowColor = this.col;
    fill(this.col);

    // blur background
    drawingContext.shadowBlur = 320;
    rect(0, 0, this.w, this.h);

    drawingContext.shadowBlur = 160;
    // rect(0, 0, this.w, this.h);

    drawingContext.shadowBlur = 80;
    // rect(0, 0, this.w, this.h);

    drawingContext.shadowBlur = 40;
    rect(0, 0, this.w, this.h);

    // blur near neon white
    drawingContext.shadowColor = color(255);
    drawingContext.shadowBlur = 5;
    // fill(lerpColor(color(255), this.col, 0.55));
    rect(0, 0, this.w, this.h);

    // reset blur
    drawingContext.shadowBlur = 0;
    if (txt) {
      fill(255);
      text(txt, 0, 0);
    }

    pop();
  }
}

