/*
	NOISE Class
*/
class PNoise {
  constructor(minimum, maximum, da = 0.01) {
    this.minimum = minimum;
    this.maximum = maximum;
    this.a = random(TWO_PI);
    this.da = da
		this.xf = random(10, 40);
		this.yf = random(10, 40);
		this.xo = random(100, 200);
		this.yo = random(1000, 2000);
  }
  getVal() {
    const x = cos(this.a) * this.xf + this.xo;
    const y = sin(this.a) * this.yf + this.yo;
    this.a += this.da;
		// return lerp(this.minimum, this.minimum, noise(x, y))
    return noise(x, y) * (this.maximum - this.minimum) + this.minimum;
  }
}

