/*
	Neon studies - #WCCChallenge "Connecting the dots" 6.11.   23
	#p5js #creativecoding #generativeart

	Dear Raph and creative coding community,

	continuing the Neon bars animation studies using a 
	connected curved rectangle structure of points, connecting 
	to a spiral. 
	- Mouse position for amount glowing bars (noise)
	- Press LMB for drawing the main anchor points
	- Double click for new scene

	Bar positions and angles calculated via:
	- https://p5js.org/reference/#/p5/curvePoint
	- https://p5js.org/reference/#/p5/curveTangent
  - see also: curveTightness()

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

const useShader = false; // Attention: curveTightness(0) must set explicitly in WEBGL
const clrs = ["red", "purple", "darkblue", "red", "purple", "darkblue", "yellow","white"];
let numC = 3; // num of roundtrip for spiral, wil lbe overridden in 
const usePNoise = true; // dont use, looks odd
let pnoise = [];
let points = [];
let bars = [];

let saveFrames = 0; // 96; // see bars.length
let neonShader;
let sbars = []; // bars to tranbsfer to shader
let fb;

function setup() {
	var minWH = max(windowWidth, windowHeight)
  createCanvas(minWH, minWH, useShader ? WEBGL : P2D); // limitation curvePoint in WEBGL mode
	describe("neon bars in the form of overlapping connected spirals, flashing ordered and randomly");
  frameRate(useShader ? 60 : 20);

	// initialize neon bars
	randomSeed(1234)
  initCurvedCircle();
	// neonShader = createShader("shader.vert", "shader.frag");
	if (useShader) {
		neonShader = createShader(vert, frag);
		fb = createFramebuffer({ format: FLOAT });
	}
	background(0, 0, 8);
}

function draw() {
  // background(0, 0, 8);
  background(0, 0, 8, 32);

	// shader
	if (useShader) {
		fb.begin();
		shaderFade();
		neonShader.setUniform('u_res', [width, height]);
		neonShader.setUniform('u_mouse', [map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, 0)]);
		neonShader.setUniform('u_time', millis()/1000.0);
		neonShader.setUniform('u_bnum', bars.length);
		neonShader.setUniform('u_bars', sbars);
		shader(neonShader);
		rect(0, 0, width, height);
		fb.end();
		imageMode(CENTER);
		image(fb, 0, 0);
	}
	else
	// no shader
	{
		if (webglVersion === "p2d") translate(width * 0.5, height * 0.5)
		for (let i = 0; i < bars.length; i++) {
			b = bars[i];
			b.act = noise(i * 0.1, frameCount * 0.15) < (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height * (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width * 0.75;
			b.act = i === (~~(frameCount/1) % bars.length) || b.act;
			b.draw();
		}
	}

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === LEFT) {
		showPoints();
	}

  if (frameCount <= saveFrames) {
    saveCanvas("neon_pn_" + nf(frameCount, 3, 0), "png");
  }

  // // noLoop() removed for animation
}

// for WEBGL Mode implement fade out
function shaderFade() {
  // [x, y, intensity, angle, ...]
  const numBars = bars.length;

	// set noise alpha/intense to max
	for (let i = 0; i < bars.length; i++) {
		let act = noise(i * 0.1, frameCount * 0.15) < (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height * (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width * 0.75;
		act = act || i === (floor(frameCount/3) % numBars);
		if (act) sbars[i * 4 + 2] = 1; 
	}

	// fade intensity out
  for (i = 2; i < sbars.length; i+=4) { // index 2 is intensity
    sbars[i] -= 0.0085125;
    if (sbars[i] < 0) sbars[i] = 0;
  }
}

// show the points
function showPoints() {
	push()
	strokeWeight(1)
	noFill();
	// show dashed lines
	stroke(128, 128); // stroke(112, 0, 16, 128)
	// drawingContext.setLineDash([10]);
	beginShape()
	for (let p of points) {
		vertex(p.x * width / 2, p.y * height / 2)
	}
	endShape(CLOSE)
	// show primary points
	strokeWeight(8)
	stroke(112, 0, 16, 128)
	for (let p of points) {
		point(p.x * width / 2, p.y * height / 2)
	}
	pop()
}

// init curved points as structure for bars
function initCurvedCircle() {
	// init basic points 
	pnoise = [];
	const pdev = 0.2;
  const pmin = pdev;
  const pmax = 1- pdev;
  pnoise.push(new PNoise(-pmin, -pmax)); // x
	numC = ~~random(2,5);
  for (let i = 0; i < numC; i++) {
    pnoise.push(new PNoise(pmin, pmax)); // y
    pnoise.push(new PNoise(pmin, pmax)); // x
    pnoise.push(new PNoise(-pmin, -pmax)); // y
    pnoise.push(new PNoise(-pmin, -pmax)); // x
  }

	// init primary points x: -1...1, y: -1...1
  points = [];
  pos = 0;
  var x, y;
  let idx = 0;
  x = random(-pmin, -pmax);
  if (usePNoise) x = pnoise[idx++].getVal();
  for (let i = 0; i < numC; i++) {
    y = random(pmin, pmax);
    if (usePNoise) y = pnoise[idx++].getVal();
    points.push({ x, y });
    x = random(pmin, pmax);
    if (usePNoise) x = pnoise[idx++].getVal();
    // y = random(0.25, 0.75);
    points.push({ x, y });
    // x = random(0.25, 0.75);
    y = random(-pmin, -pmax);
    if (usePNoise) y = pnoise[idx++].getVal();
    points.push({ x, y });
    x = random(-pmin, -pmax);
    if (usePNoise) x = pnoise[idx++].getVal();
    // y = random(-0.25, -0.75);
    points.push({ x, y });
  }
	// adjust x-coord of last anchor point to first
  points[points.length - 1].x = points[0].x;

	// generate bars based on intermediate points on the curve
  bars = [];
	sbars = []; // [0.0,0.0,0.7,0.0];
  const sz = 40;
  const dt = (sz / max(width, height)) * 2;
	curveTightness(0); // needed for WEBGL
  for (let i = 0; i < points.length; i++) {
    // const t = (frameCount % fR) / fR;
    for (let t = 0; t < 1; t += dt) {
      const pa = points[(i - 2 + points.length) % points.length];
      const pb = points[(i - 1 + points.length) % points.length];
      const pc = points[(i + points.length) % points.length];
      const pd = points[(i + 1 + points.length) % points.length];
      const cx = curvePoint(pa.x, pb.x, pc.x, pd.x, t);
      const cy = curvePoint(pa.y, pb.y, pc.y, pd.y, t);
      const tx = curveTangent(pa.x, pb.x, pc.x, pd.x, t);
      const ty = curveTangent(pa.y, pb.y, pc.y, pd.y, t);
      const angle = atan2(ty, tx); //  - PI / 2.0;
      // for P2D: 1 entry per bar
			bars.push(new Bar(cx, cy, sz, 6, random(clrs), angle));
			bars[bars.length-1].act = true;
			// for WebGL: 4 entries per bar
			sbars.push(cx)
			sbars.push(cy)
			sbars.push(0.75)
			sbars.push(angle)
    }
  }

	// reduce num bars for WebGL
	if (webglVersion !== "p2d") {
		const redNum = 200; // adjust, when shader has a limit
		bars.splice(redNum, Infinity)
		sbars.splice(redNum * 4, Infinity) 
	}

  const da = TWO_PI / bars.length / 100;
  for (let pn of pnoise) {
    pn.da = da;
  }
}
